{
  "technical_and_design_decisions": [
    "Use Gradle for build automation and dependency management.",
    "Use Testcontainers for managing external Kafka broker in tests.",
    "Use existing logging framework (Logback/Log4j) configuration for date in logs.",
    "Follow existing project structure for samples and deployment scripts.",
    "Sonar violations will be reviewed in SonarQube UI and fixed in code or marked as false positives."
  ],
  "assumptions": [
    "The codebase is using Gradle as build tool.",
    "The project has a wiki (e.g., GitHub Wiki) for documentation.",
    "The Spark streaming module already exists and only deployment ease is needed.",
    "The Kafka tests currently use embedded Kafka and can be migrated to external broker without major test logic changes.",
    "The central dependency list (dependencies.properties) exists and contains required versions.",
    "Sonar violations count is moderate (~100) and most are straightforward.",
    "The Spark batch job sample can be based on existing Spark examples.",
    "Development environment has Java 17+ and necessary tools.",
    "No major refactoring of existing code is required beyond the specified changes."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Implement easy deployment for Spark streaming module (Scala)",
      "activity_description": "Create deployment scripts, update documentation, and test deployment process for the Scala-based Spark streaming module.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A2",
      "activity_name": "Update wiki with ulimit troubleshooting section",
      "activity_description": "Add a new troubleshooting section to the project wiki documenting the recommended ulimit setting (10K) and the 'Too many open files' exception.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "A3",
      "activity_name": "Modify logger properties to include date in logs",
      "activity_description": "Adjust the xd-container-logger.properties file to include date in log output for better troubleshooting.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "A4",
      "activity_name": "Refactor Kafka tests to use external Kafka broker",
      "activity_description": "Change Kafka tests to run against an external Kafka broker (separate process) using Testcontainers or similar, improving build experience and reducing build footprint (covers U4 and U6).",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A5",
      "activity_name": "Update publish-maven.gradle to use central dependency list",
      "activity_description": "Modify the publish-maven.gradle script to read dependency versions (e.g., Spring Boot, hadoop-common) from dependencies.properties.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A6",
      "activity_name": "Review and fix Sonar violations",
